// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"coin-vs-token":{"slug":"coin-vs-token","cat":"basics","en":"Coin vs token","contentLocale":"en","term":"Coin vs token","aka":["coin or token","native coin","crypto token"],"short":"A coin is the native asset of its own blockchain, such as BTC or ETH, while a token is an asset created on top of an existing blockchain using a smart contract, such as USDT on Ethereum.","body":[["A coin is built into the protocol of its ",["blockchain","blockchain"],". It usually pays transaction fees and rewards miners or validators: ",["BTC","bitcoin"]," on Bitcoin, ",["ETH","ethereum"]," on Ethereum, SOL on Solana. A token is created by a ",["smart contract","smart-contract"]," that runs on someone else's chain, following a standard such as ERC20 on Ethereum or SPL on Solana."],["This difference matters most when you move funds. A token like ",["USDT","usdt"]," exists on several chains at once, and each version lives at a different contract. When you withdraw, the exchange asks you to choose a network. The ",["receiving address","wallet-address"]," must support the same network, or the transfer can fail or be lost."],"It also matters for fees. To move a token you pay gas in the chain's coin, not in the token. Holding 100 USDT on Ethereum is not enough to send it; you also need a little ETH in the same wallet. In casual speech people mix the two words, and many exchanges simply call everything a coin."],"example":"Suppose you hold 300 USDT on the Tron network in a wallet with zero TRX. When you try to send the USDT, the wallet warns that you lack resources for the fee. You buy 20 TRX, send it to the wallet, and the transfer goes through. The same 300 USDT on Arbitrum would need a small amount of ETH on Arbitrum instead, because each token pays fees in its host chain's coin.","mistakes":["Choosing a different withdrawal network from the one the receiving exchange or wallet supports.","Trying to send a token from a wallet that holds none of the chain's native coin for gas.","Adding a token by name in a wallet without checking the contract address, which is how fake tokens get displayed."],"faq":[{"q":"Is USDT a coin or a token?","a":"USDT is a token. Tether issues it on several blockchains, including Ethereum, Tron and Solana, each as a separate contract."},{"q":"Can a token become a coin?","a":"Yes, some projects start as tokens on Ethereum and later launch their own blockchain, then swap holders into the new native coin in a migration."},{"q":"Why does my exchange call everything a coin?","a":"It is a simplification for users. On the deposit and withdrawal screens, the network selector shows which chain the asset actually lives on."}],"title":"Coin vs token: what is the difference in crypto?","description":"Learn the difference between a coin and a token, why networks matter for withdrawals, and which coin pays the gas.","related":[["layer-1","Layer 1 (L1)","A layer 1 (L1) is a base blockchain that processes and finalises transactions on its own network with its own consensus and native coin, such as Bitcoin, Ethereum or Solana."],["smart-contract","Smart contract","A smart contract is a program stored on a blockchain that runs automatically when its conditions are met, letting people trade, lend or issue tokens without a middleman."],["governance-token","Governance token","A governance token is a crypto token that gives holders the right to vote on a protocol's decisions, such as fee changes, upgrades and treasury spending, in proportion to the tokens they hold or delegate."],["tokenomics","Tokenomics","Tokenomics is the economic design of a cryptocurrency, covering how many tokens exist, who received them, how new tokens are released and what the token is actually used for."],["altcoin","Altcoin","An altcoin is any cryptocurrency other than Bitcoin, a broad category that includes Ether, Solana, stablecoins, exchange tokens and memecoins."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"memecoin":{"slug":"memecoin","cat":"basics","en":"Memecoin","contentLocale":"en","term":"Memecoin","aka":["meme coin","meme token"],"short":"A memecoin is a cryptocurrency inspired by an internet joke, animal or cultural trend, whose price is driven mainly by community attention rather than a product or cash flow.","body":[["Dogecoin, launched in 2013 as a joke about a Shiba Inu dog meme, is the original memecoin. Since then thousands have followed, especially on Solana, ",["Ethereum","ethereum"]," and BNB Chain, where anyone can create a token in minutes through launch platforms."],["Memecoins can rise many times over in days when social media attention spikes, and they can lose most of their value just as quickly. Many have huge supplies, little ",["liquidity","liquidity"]," and concentrated holders. Early buyers or the creators often hold a large share and can sell into new demand."],["If you trade memecoins, size positions so that losing the whole amount would not hurt you. Check whether liquidity is locked, how much supply the top wallets hold, whether the ",["contract","smart-contract"]," can mint more tokens, and whether the token is listed on established exchanges. A large ",["exchange listing","token-listing"]," increases access, but it does not make the token less volatile."]],"example":["Suppose you put 100 ",["USDT","usdt"]," into a new memecoin at 0.0002 USDT per token, buying 500,000 tokens. Two days later it trades at 0.0006, and your holding is worth 300 USDT. A week after that, the creator wallet sells and the price drops to 0.00005. Your tokens are now worth 25 USDT, a 75 percent loss from your entry and over 90 percent from the peak."],"mistakes":["Buying after a token has already risen several hundred percent because of FOMO.","Ignoring holder concentration and liquidity, then being unable to sell without crashing the price.","Confusing a copycat token with the real one because it uses the same name and ticker."],"faq":[{"q":"What was the first memecoin?","a":"Dogecoin (DOGE), created in 2013, is widely considered the first memecoin."},{"q":"Are memecoins a scam?","a":"Not all of them, but the category has many rug pulls and pump-and-dump schemes. Even legitimate memecoins are highly speculative because their value depends on attention."},{"q":"Why do memecoins have such huge supplies?","a":"A huge supply makes the price per token tiny, which feels cheap to buyers. What matters is market cap, not the unit price."}],"title":"What is a memecoin? Meaning, examples and risks","description":"Learn what a memecoin is, why meme tokens swing so hard and what to check before buying one.","related":[["altcoin","Altcoin","An altcoin is any cryptocurrency other than Bitcoin, a broad category that includes Ether, Solana, stablecoins, exchange tokens and memecoins."],["rug-pull","Rug pull","A rug pull is a scam where the creators of a crypto project suddenly drain its liquidity, dump their tokens or abandon it after attracting buyers, leaving the token close to worthless."],["volatility","Volatility","Volatility is a measure of how much and how quickly an asset's price moves up and down over a given period, and higher volatility means larger, faster swings."],["liquidity","Liquidity","Liquidity is how easily you can buy or sell an asset quickly, in size, without moving its price much."],["dex","Decentralized exchange (DEX)","A decentralized exchange (DEX) is a trading platform that runs on smart contracts, letting you swap tokens directly from your own wallet without depositing funds with a company."]],"lesson":null,"coin":{"slug":"dogecoin","name":"Dogecoin","symbol":"DOGE"},"tool":"/topics/meme-coins","cta":true},"hodl":{"slug":"hodl","cat":"basics","en":"HODL","contentLocale":"en","term":"HODL","aka":["hold on for dear life","hodler","hodling"],"short":"HODL is crypto slang for holding an asset for the long term instead of selling during price drops, originating from a misspelling of \"hold\" in a 2013 Bitcoin forum post.","body":["During a sharp price drop in December 2013, a user on the Bitcointalk forum posted that they were \"hodling\", a typo of holding. The word stuck, and many later turned it into the backronym \"hold on for dear life\". Today a hodler is someone who buys and plans to keep their coins through ups and downs.",["HODLing is a strategy, not a guarantee. It has worked for some assets over long periods, but many coins that people held for years never recovered. A thoughtful approach involves holding only assets you understand, keeping ",["position size","position-sizing"]," within what you can afford to see fall a long way, and storing coins safely."],["Long-term holders often move coins to a ",["self-custody wallet","non-custodial-wallet"],", such as a ",["hardware wallet","hardware-wallet"],", so they do not depend on a single exchange. If you do that, back up your ",["seed phrase","seed-phrase"]," offline and check the ",["receiving address","wallet-address"]," and network carefully when withdrawing."]],"example":["Suppose you buy 0.1 ",["BTC","bitcoin"]," at 40,000 USDT, spending 4,000 USDT. Six months later BTC drops to 24,000 and your holding is worth 2,400 USDT, down 40 percent. A hodler does not sell. If BTC later trades at 60,000 USDT, the same 0.1 BTC is worth 6,000 USDT, a 50 percent gain on the original 4,000. But if you had held a small altcoin that never recovered, the same patience would have locked in the loss."],"mistakes":["Holding any coin forever without checking whether the project is still active.","Putting money you need soon into a long-term hold.","Leaving long-term holdings on an exchange without considering custody risk."],"faq":[{"q":"What does HODL stand for?","a":"It started as a typo of hold in 2013. Many people now say it stands for hold on for dear life, but that meaning came later."},{"q":"Is HODLing a good strategy?","a":"It depends on what you hold, how much and for how long. It avoids overtrading and emotional selling, but it also means sitting through big drawdowns."},{"q":"What is a hodler?","a":"A hodler is someone who buys crypto and keeps it for the long term instead of trading in and out."}],"title":"What does HODL mean? Origin and meaning in crypto","description":"Learn what HODL means, where the term came from and what to consider before holding crypto long term.","related":[["dollar-cost-averaging","Dollar-cost averaging (DCA)","Dollar-cost averaging (DCA) is a strategy of buying a fixed amount of an asset at regular intervals, regardless of price, to spread your entry over time."],["cold-wallet","Cold wallet (cold storage)","A cold wallet is a way of storing crypto where the private keys are generated and kept offline, away from internet-connected devices, so remote attackers cannot reach them."],["bear-market","Bear market","A bear market is a sustained period of falling prices and pessimistic sentiment, commonly described as a decline of 20 percent or more from a recent high."],["volatility","Volatility","Volatility is a measure of how much and how quickly an asset's price moves up and down over a given period, and higher volatility means larger, faster swings."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"liquidity-pool":{"slug":"liquidity-pool","cat":"defi","en":"Liquidity pool","contentLocale":"en","term":"Liquidity pool","aka":["LP","pool"],"short":"A liquidity pool is a smart contract holding two or more tokens that traders swap against on a DEX, funded by liquidity providers who earn a share of the trading fees.","body":[["When you add ",["liquidity","liquidity"],", you usually deposit both tokens of a pair in the current price ratio, for example ",["ETH","ethereum"]," and ",["USDC","usdc"],". In return you get LP tokens or an ",["NFT","nft"]," position that represents your share of the pool. When you withdraw, you receive your share of whatever is in the pool at that time, plus fees earned."],["Your earnings come from trading fees, sometimes topped up by token rewards. Your risks include ",["impermanent loss","impermanent-loss"]," when prices move, ",["smart contract","smart-contract"]," bugs, and for new tokens, the chance that the token itself collapses or is a rug pull."],"Pool depth matters to traders too. The more value in a pool, the smaller the price impact of each trade. That is why total liquidity is one of the first numbers to check before buying a small token on a DEX."],"example":"Say a pool holds 500,000 USDC and 200 ETH, at 2,500 USDC per ETH, for a total of 1,000,000 USDC. You add 5,000 USDC and 2 ETH, which equals 1 percent of the pool. Over a month, traders pay 30,000 USDC in fees to the pool. Your 1 percent share earns about 300 USDC, before any impermanent loss and gas costs.","mistakes":["Looking only at the advertised APR and ignoring impermanent loss and token risk.","Providing liquidity for a token whose pool liquidity is controlled by the team.","Losing or transferring the LP tokens that represent your position."],"faq":[{"q":"How do liquidity pools make money?","a":"They collect a fee on every swap, which is shared among liquidity providers in proportion to their share of the pool."},{"q":"Can I lose money in a liquidity pool?","a":"Yes. Price moves cause impermanent loss, and a smart contract bug or token collapse can cause larger losses."}],"title":"What is a liquidity pool? How LPs earn and lose","description":"What a liquidity pool is, how liquidity providers earn trading fees, and the risks of impermanent loss and rug pulls.","related":[["amm","Automated market maker (AMM)","An automated market maker (AMM) is a type of DEX that prices trades with a mathematical formula based on the tokens held in a liquidity pool, instead of matching buyers and sellers in an order book."],["impermanent-loss","Impermanent loss","Impermanent loss is the shortfall a liquidity provider has compared with simply holding the same tokens, caused by the prices of the pooled tokens moving apart after the deposit."],["yield-farming","Yield farming","Yield farming is the practice of moving crypto into DeFi protocols, such as liquidity pools or lending markets, to earn trading fees, interest and extra token rewards."],["rug-pull","Rug pull","A rug pull is a scam where the creators of a crypto project suddenly drain its liquidity, dump their tokens or abandon it after attracting buyers, leaving the token close to worthless."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"perp-dex":{"slug":"perp-dex","cat":"defi","en":"Perp DEX (on-chain perpetuals)","contentLocale":"en","term":"Perp DEX (on-chain perpetuals)","aka":["perp DEX","perpetual DEX","on-chain perps","decentralized perpetual exchange"],"short":"A perp DEX is a decentralized exchange for perpetual futures, letting you trade with leverage from your own wallet while margin, positions and settlement are handled on-chain or on a dedicated chain.","body":[["Perp DEXs use the same building blocks as ",["perpetual futures","perpetual-futures"]," on centralized exchanges: margin, ",["leverage","leverage"],", ",["mark price","mark-price"],", ",["funding rate","funding-rate"]," and ",["liquidation","liquidation"],". Hyperliquid runs an on-chain ",["order book","order-book"]," on its own chain. GMX and similar platforms let traders trade against a liquidity pool priced by oracles. dYdX runs an order book on its own chain."],"The main appeal is self-custody: you deposit margin from your wallet without opening an exchange account, and positions are visible on-chain. The trade-offs include smart contract or chain risk, sometimes thinner liquidity for smaller markets, oracle dependence, and the need to manage gas and bridging.","Funding intervals, fee models, maximum leverage and liquidation rules differ from platform to platform and from centralized exchanges. Read the contract specifications of the market you trade."],"example":"Suppose you deposit 1,000 USDC to a perp DEX and open a 5x long on ETH at 2,500, a position worth 5,000 USDC. If ETH rises 4 percent to 2,600, the position gains about 200 USDC, a 20 percent return on margin, before fees and funding. If ETH falls 4 percent, you lose about 200 USDC. A fall of roughly 15 to 19 percent, depending on the maintenance margin, could liquidate the position.","mistakes":["Assuming funding intervals and fees are the same as on your usual centralized exchange.","Using maximum leverage on a small market with thin liquidity.","Forgetting that bridging margin to a perp DEX's chain adds its own steps and risks."],"faq":[{"q":"Is Hyperliquid a DEX?","a":"Hyperliquid is an on-chain perpetual exchange that runs on its own blockchain, so trades and positions are recorded on-chain and users trade from self-custody wallets."},{"q":"Do perp DEXs require KYC?","a":"Most do not require identity checks to use the contracts, though some block access from certain countries through their front-end."}],"title":"What is a perp DEX? On-chain perpetuals explained","description":"What a perp DEX is, how on-chain perpetual futures work, and how they differ from perpetuals on centralized exchanges.","related":[["perpetual-futures","Perpetual futures (perps)","Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price."],["dex","Decentralized exchange (DEX)","A decentralized exchange (DEX) is a trading platform that runs on smart contracts, letting you swap tokens directly from your own wallet without depositing funds with a company."],["funding-rate","Funding rate","A funding rate is a periodic payment between long and short traders that keeps a perpetual futures price close to the spot price."],["non-custodial-wallet","Non-custodial wallet (self-custody wallet)","A non-custodial wallet is a crypto wallet where you alone hold the private keys or seed phrase, so no exchange or company can move, freeze or recover your funds for you."]],"lesson":null,"coin":{"slug":"hyperliquid","name":"Hyperliquid","symbol":"HYPE"},"tool":"/funding-rates","cta":false},"copy-trading":{"slug":"copy-trading","cat":"exchange-features","en":"Copy trading","contentLocale":"en","term":"Copy trading","aka":["copytrading","social trading","mirror trading"],"short":"Copy trading is an exchange feature that automatically mirrors another trader's positions in your own account, in proportion to the amount you allocate.","body":["On copy trading platforms, experienced traders, often called lead traders, publish their performance. You pick one, allocate funds, and the system opens and closes trades in your account when they do. OKX, Bybit and Bitget all offer copy trading, for both spot and futures, though the details differ.",["Most lead traders earn a share of their followers' profits, commonly a profit-sharing percentage on net gains. You keep control over settings such as the amount per trade, a maximum ",["position size","position-sizing"],", ",["leverage","leverage"]," limits and a ",["stop loss","stop-loss"]," for the whole copy portfolio. Check whether the copy follows the lead's leverage or uses your own setting."],["The main risks are that past results do not guarantee future ones, futures copy trading can be liquidated just like manual trading, and your entry price can differ slightly from the lead's because of ",["slippage","slippage"],". Look beyond headline return: check maximum drawdown, how long the track record is, the number of followers and how much capital the lead trader risks themselves."]],"example":["Suppose you allocate 1,000 ",["USDT","usdt"]," to copy a futures trader with a 10% profit share. The lead uses 5x leverage and puts 20% of their balance into each trade, so your account opens a 200 USDT margin position worth 1,000 USDT. If the price moves 4% in the lead's favour, your position gains 40 USDT and you pay 4 USDT profit share. If it moves 4% against, you lose 40 USDT with no profit share. A 20% move against at 5x would wipe out that 200 USDT margin."],"mistakes":["Picking a lead trader based only on a 30-day return that came from one lucky high-leverage trade.","Copying without setting a total stop loss for the copy portfolio.","Allocating money you need soon, without accounting for drawdowns that even good traders experience."],"faq":[{"q":"Is copy trading profitable?","a":"It can be, but results depend entirely on the trader you copy and the market. Many followers lose money when they choose leads by short-term returns alone."},{"q":"Can I lose more than I put into copy trading?","a":"On most exchanges, losses are limited to the funds allocated to the copy, but futures copies can lose that full amount through liquidation."}],"title":"What is copy trading in crypto? How it works","description":"How crypto copy trading works, how lead traders are paid, which settings protect you and what risks come with copying futures.","related":[["perpetual-futures","Perpetual futures (perps)","Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price."],["leverage","Leverage","Leverage is using borrowed funds or margin to open a position larger than your own capital, which multiplies both profits and losses."],["risk-reward-ratio","Risk-reward ratio","The risk-reward ratio compares how much you could lose on a trade, up to your stop-loss, with how much you could gain, up to your take-profit target."],["grid-trading-bot","Grid trading bot","A grid trading bot is an automated tool that places a ladder of buy and sell limit orders within a price range, profiting from repeated moves up and down."]],"lesson":null,"coin":null,"tool":"/compare","cta":true}});
